if has_nx:
    from MDAnalysis.analysis.leaflet import LeafletFinder

    # Ensure valid dimensions for pbc=True
    if universe.dimensions is None or universe.dimensions[0] == 0:
        try:
            universe.dimensions = [100.0, 100.0, 100.0, 90.0, 90.0, 90.0]
        except Exception:
            pass

    pbc_flag = (universe.dimensions is not None and universe.dimensions[0] > 0)

    # Fallback if no phosphorus atoms are present in the test Universe
    head_sel = "name P*"
    if len(universe.select_atoms(head_sel)) == 0:
        head_sel = "name CA and resid 1:30"

    # Initialize LeafletFinder
    lfls = LeafletFinder(universe, head_sel, pbc=pbc_flag)

    # Unpack all leaflets
    leaflets = lfls.groups()

    assert isinstance(leaflets, (tuple, list)), "groups() should return a sequence of AtomGroups"

    if len(leaflets) > 0:
        # Extract full residues for the first leaflet
        leaflet0_lipids = leaflets[0].residues.atoms
        witness = len(leaflet0_lipids)
        assert witness >= len(leaflets[0]), "Residues should contain at least as many atoms as the head groups"
    else:
        witness = 0

    print(f"__CHECK__ LeafletFinder {len(leaflets)} leaflets, first has {witness} atoms")
else:
    print("__CHECK__ LeafletFinder skipped due to missing networkx")

